CREATE TABLE qc_metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  date TEXT NOT NULL,
  pass_rate REAL DEFAULT 98.6,
  defect_count INTEGER DEFAULT 14,
  gemba_issues INTEGER DEFAULT 3,
  oee REAL DEFAULT 91.5
