CREATE TABLE room_bookings (id TEXT PRIMARY KEY, room_id TEXT NOT NULL, room_name TEXT NOT NULL, title TEXT NOT NULL, booker_name TEXT NOT NULL, department TEXT NOT NULL, booking_date TEXT NOT NULL, time_slot TEXT NOT NULL, attendees_count INTEGER DEFAULT 5, notes TEXT, status TEXT DEFAULT 'CONFIRMED', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, version INTEGER DEFAULT 1);
CREATE TABLE visitors (id TEXT PRIMARY KEY, badge_code TEXT NOT NULL UNIQUE, visitor_name TEXT NOT NULL, company TEXT NOT NULL, id_card TEXT, host_name TEXT NOT NULL, department TEXT NOT NULL, room_location TEXT NOT NULL, visit_date TEXT NOT NULL, expected_time TEXT NOT NULL, status TEXT DEFAULT 'EXPECTED', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_trips (id TEXT PRIMARY KEY, code TEXT NOT NULL, title TEXT NOT NULL, region TEXT DEFAULT 'VP Chuỗi', factory TEXT, creator TEXT NOT NULL, department TEXT NOT NULL, location TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, days_count INTEGER DEFAULT 1, transport TEXT DEFAULT 'Xe công ty', participants_count INTEGER DEFAULT 1, purpose TEXT, address TEXT, proposal_text TEXT, participants_json TEXT, status TEXT DEFAULT 'PENDING', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, estimated_cost REAL DEFAULT 0.0, approved_level TEXT, l1_approved_by TEXT, l1_approved_at DATETIME, l2_approved_by TEXT, l2_approved_at DATETIME, rejection_reason TEXT, version INTEGER DEFAULT 1, attachments_json TEXT, invoices_json TEXT, creator_emp_code TEXT, rejected_level TEXT, budget_status TEXT DEFAULT 'pending_dept_budget', budget_amount REAL DEFAULT 0, budget_rejection_reason TEXT, legacy_code TEXT);
