CREATE TABLE roles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    code TEXT NOT NULL UNIQUE,
    level INTEGER NOT NULL DEFAULT 4,
    department_id INTEGER,
    description TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL
);
CREATE TABLE permissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    module TEXT NOT NULL,
    action TEXT NOT NULL
);
CREATE TABLE role_permissions (
    role_id INTEGER NOT NULL,
    permission_id INTEGER NOT NULL,
    PRIMARY KEY (role_id, permission_id),
    FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,
    FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE
);
CREATE TABLE branches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    region TEXT NOT NULL,
    address TEXT
);
CREATE TABLE sectors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    code TEXT NOT NULL UNIQUE
);
CREATE TABLE zones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    description TEXT
);
CREATE TABLE lines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    zone_id INTEGER NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE
);
CREATE TABLE machines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    machine_code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    serial_number TEXT,
    zone_id INTEGER,
    line_id INTEGER,
    branch_id INTEGER,
    status TEXT DEFAULT 'OPERATING', -- OPERATING, WARNING, DOWN, MAINTENANCE
    install_date TEXT,
    specs TEXT,
    qr_code_data TEXT UNIQUE,
    grid_x INTEGER DEFAULT 0,
    grid_y INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE SET NULL,
    FOREIGN KEY (line_id) REFERENCES lines(id) ON DELETE SET NULL,
    FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
);
CREATE TABLE incident_categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    default_priority TEXT DEFAULT 'MEDIUM', -- LOW, MEDIUM, HIGH, CRITICAL
    estimated_fix_time_mins INTEGER DEFAULT 30
);
CREATE TABLE maintenance_tickets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_code TEXT NOT NULL UNIQUE,
    machine_id INTEGER NOT NULL,
    reported_by_id INTEGER NOT NULL,
    assigned_to_id INTEGER,
    category_id INTEGER,
    branch_id INTEGER,
    priority TEXT DEFAULT 'MEDIUM',
    status TEXT DEFAULT 'OPEN', -- OPEN, ASSIGNED, IN_PROGRESS, RESOLVED, CLOSED
    description TEXT,
    image_url TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    accepted_at DATETIME,
    started_at DATETIME,
    completed_at DATETIME,
    response_time_sec INTEGER DEFAULT 0,
    resolution_time_sec INTEGER DEFAULT 0,
    total_downtime_sec INTEGER DEFAULT 0,
    root_cause TEXT,
    resolution_notes TEXT,
    spare_parts_used TEXT,
    estimated_repair_cost REAL DEFAULT 0.0,
    approval_status TEXT DEFAULT 'APPROVED', created_by TEXT, assigned_to TEXT, resolved_note TEXT, resolved_at DATETIME, reopen_reason TEXT, source_module TEXT, source_record_id TEXT, version INTEGER DEFAULT 1, code TEXT, legacy_code TEXT, team_code TEXT,
    FOREIGN KEY (machine_id) REFERENCES machines(id),
    FOREIGN KEY (reported_by_id) REFERENCES users(id),
    FOREIGN KEY (assigned_to_id) REFERENCES users(id),
    FOREIGN KEY (category_id) REFERENCES incident_categories(id),
    FOREIGN KEY (branch_id) REFERENCES branches(id)
);
CREATE TABLE maintenance_performance_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    mechanic_id INTEGER NOT NULL,
    log_date TEXT NOT NULL,
    tickets_resolved INTEGER DEFAULT 0,
    avg_resolution_mins REAL DEFAULT 0.0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (mechanic_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE documents_templates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    doc_type TEXT NOT NULL, -- LEAVE, PROPOSAL, QC_REPORT, MAINTENANCE_REQ, OTHER
    department_id INTEGER,
    file_r2_key TEXT NOT NULL,
    file_type TEXT NOT NULL, -- docx, pdf
    placeholders_json TEXT NOT NULL, -- JSON array of detected placeholder keys & form schema
    created_by_id INTEGER NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (department_id) REFERENCES departments(id),
    FOREIGN KEY (created_by_id) REFERENCES users(id)
);
CREATE TABLE documents_generated (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    template_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    creator_id INTEGER NOT NULL,
    department_id INTEGER,
    form_data_json TEXT NOT NULL,
    file_r2_key TEXT NOT NULL,
    status TEXT DEFAULT 'PENDING', -- PENDING, APPROVED, REJECTED
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (template_id) REFERENCES documents_templates(id),
    FOREIGN KEY (creator_id) REFERENCES users(id),
    FOREIGN KEY (department_id) REFERENCES departments(id)
);
CREATE TABLE document_approval_flow (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id INTEGER NOT NULL,
    step_order INTEGER NOT NULL,
    approver_role_id INTEGER,
    approver_id INTEGER,
    status TEXT DEFAULT 'PENDING', -- PENDING, APPROVED, REJECTED
    comments TEXT,
    actioned_at DATETIME,
    FOREIGN KEY (document_id) REFERENCES documents_generated(id) ON DELETE CASCADE,
    FOREIGN KEY (approver_role_id) REFERENCES roles(id),
    FOREIGN KEY (approver_id) REFERENCES users(id)
);
CREATE TABLE jobs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    requirements TEXT NOT NULL,
    location TEXT DEFAULT 'Văn Phòng Chuỗi SKECHERS',
    department_id INTEGER,
    status TEXT DEFAULT 'ACTIVE', -- ACTIVE, CLOSED
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, version INTEGER DEFAULT 1,
    FOREIGN KEY (department_id) REFERENCES departments(id)
);
CREATE TABLE job_applications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    job_id INTEGER NOT NULL,
    candidate_name TEXT NOT NULL,
    candidate_email TEXT NOT NULL,
    candidate_phone TEXT NOT NULL,
    cv_r2_key TEXT,
    cover_letter TEXT,
    status TEXT DEFAULT 'SUBMITTED', -- SUBMITTED, REVIEWING, ACCEPTED, REJECTED
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, version INTEGER DEFAULT 1,
    FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
);
CREATE TABLE notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    type TEXT DEFAULT 'INFO',
    is_read INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, module TEXT, record_id TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    action TEXT NOT NULL,
    target_entity TEXT,
    details TEXT,
    ip_address TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    emp_code TEXT NOT NULL UNIQUE,
    email TEXT UNIQUE,
    name TEXT NOT NULL,
    phone TEXT,
    password_hash TEXT NOT NULL DEFAULT '123456',
    role_id INTEGER DEFAULT 5,
    department_id INTEGER DEFAULT 1,
    title TEXT,
    department TEXT,
    role_code TEXT,
    status TEXT DEFAULT 'ACTIVE',
    avatar_url TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, version INTEGER DEFAULT 1, ngay_vao TEXT, vtcv_hien_tai TEXT, vtcv_sap TEXT, vtcv_sap_xep TEXT, bo_phan_moi TEXT, phong_ban_hien_tai TEXT, pb_sap_xep TEXT, factory_id TEXT, workshop_id TEXT, line_id TEXT, chuyen_id TEXT, to_id TEXT, vtcv TEXT);
