CREATE TABLE user_profile (
    id TEXT PRIMARY KEY,
    emp_code TEXT,
    name TEXT NOT NULL,
    email TEXT,
    phone TEXT,
    avatar TEXT,
    title TEXT,
    department TEXT,
    role_code TEXT,
    redirect_url TEXT,
