CREATE TABLE idempotency_logs (
    key TEXT PRIMARY KEY,
    endpoint TEXT NOT NULL,
    response_json TEXT NOT NULL,
    status_code INTEGER DEFAULT 200,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE qc_defect_reports (
    id TEXT PRIMARY KEY,
    status TEXT DEFAULT 'REPORTED', -- REPORTED, INVESTIGATING, ACTION_REQUIRED, RESOLVED, VERIFIED
    created_by TEXT NOT NULL,
    description TEXT NOT NULL,
    action_required_note TEXT,
    resolved_at DATETIME,
    verified_by TEXT,
    verified_at DATETIME,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, code TEXT, legacy_code TEXT, team_code TEXT);
CREATE TABLE qc_kaizen_submissions (
    id TEXT PRIMARY KEY,
    status TEXT DEFAULT 'SUBMITTED', -- SUBMITTED, UNDER_REVIEW, APPROVED, REJECTED, IMPLEMENTED
    submitted_by TEXT NOT NULL,
    description TEXT NOT NULL,
    review_note TEXT,
    reviewed_by TEXT,
    reviewed_at DATETIME,
    implemented_at DATETIME,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE finance_advances (
    id TEXT PRIMARY KEY,
    emp_code TEXT NOT NULL,
    amount REAL NOT NULL,
    purpose TEXT,
    status TEXT DEFAULT 'DRAFT', -- DRAFT, PENDING_L1, PENDING_L2, APPROVED, REJECTED
    approved_level TEXT,
    l1_approved_by TEXT,
    l1_approved_at DATETIME,
    l2_approved_by TEXT,
    l2_approved_at DATETIME,
    rejection_reason TEXT,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, code TEXT, legacy_code TEXT);
CREATE TABLE approval_thresholds (
    module TEXT PRIMARY KEY,
    threshold_amount REAL DEFAULT 5000000.0,
    updated_by TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
