CREATE TABLE ci_kaizen_proposals (
    id TEXT PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    category TEXT NOT NULL, -- PRODUCTIVITY, COST_SAVING, SAFETY, AUTOMATION, 5S, MATERIAL_SAVING, EQUIPMENT, OTHER
    category_label TEXT NOT NULL, -- 3.Tăng Năng suất, 1.Tiết kiệm Vật tư, 4.An toàn lao động, etc.
    registration_type TEXT DEFAULT 'THI_DUA', -- THI_DUA, LUU_TRU
    sub_status TEXT DEFAULT 'CHO_DANH_GIA', -- DA_DANH_GIA, CHO_DANH_GIA
    region TEXT NOT NULL, -- LONG XUYÊN, ĐẾ, ĐÀ NẴNG, HỘI AN, ĐỒNG XOÀI...
    department TEXT NOT NULL,
    factory TEXT,
    proposer_name TEXT NOT NULL,
    proposer_emp_code TEXT NOT NULL,
    dept_code TEXT DEFAULT 'SK', -- DP, SK, RB, WR, Khác
    before_description TEXT,
    after_solution TEXT,
    saved_seconds INTEGER DEFAULT 0,
    before_image_url TEXT,
    after_image_url TEXT,
    attachments_json TEXT,
    status TEXT DEFAULT 'SUBMITTED', -- SUBMITTED, UNDER_REVIEW, APPROVED, REJECTED, IMPLEMENTED
    award_title TEXT, -- Giải Nhất, Giải Nhì, Giải Ba, Giải Khuyến Khích
    score_points REAL DEFAULT 0.0,
    avg_rating REAL DEFAULT 0.0,
    rating_count INTEGER DEFAULT 0,
    vote_count INTEGER DEFAULT 0,
    view_count INTEGER DEFAULT 0,
    rejection_reason TEXT,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, required_reviewer_ids_json TEXT, average_score REAL, evaluated_at DATETIME, comments TEXT, review_comment TEXT, proposer_position TEXT, proposer_month INTEGER, proposer_year INTEGER, hr_suggestor TEXT, customer TEXT, product_group TEXT, product_code TEXT, quantity INTEGER, pricing_direction TEXT, time_before_seconds INTEGER, time_after_seconds INTEGER, efficiency_value_vnd INTEGER, legacy_code TEXT, team_code TEXT, plant_code TEXT DEFAULT 'VP2_SKECHERS', approval_status TEXT DEFAULT 'PENDING', evaluation_result TEXT DEFAULT 'PENDING', approved_by TEXT, approved_at TEXT, evaluated_by TEXT, review_status TEXT DEFAULT 'CHO_PHE_DUYET', is_archived INTEGER DEFAULT 0);
