CREATE UNIQUE INDEX idx_users_emp_code ON users(emp_code);
CREATE UNIQUE INDEX idx_room_booking_unique ON room_bookings(room_id, booking_date, time_slot) WHERE status != 'CANCELLED';
CREATE UNIQUE INDEX idx_room_booking_slot 
              ON room_bookings (room_id, booking_date, time_slot) 
              WHERE status != 'CANCELLED';
